class BillingTestDB extends PDO {
 public function prepare(string $sql,array $options=[]): PDOStatement|false {return parent::prepare(str_replace([' FOR UPDATE','INSERT IGNORE'],['','INSERT OR IGNORE'],$sql),$options);}
 public function exec(string $sql): int|false {if(preg_match('/^CREATE TABLE IF NOT EXISTS (numi_\w+)/',$sql,$m)){if($this->query("SELECT 1 FROM sqlite_master WHERE name='".$m[1]."'")->fetchColumn())return 0;}return parent::exec($sql);}
}
$db=new BillingTestDB('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);@$db->sqliteCreateFunction('UTC_TIMESTAMP',fn()=>gmdate('Y-m-d H:i:s'));
$db->exec("CREATE TABLE numi_accounts(id TEXT PRIMARY KEY,email TEXT,display_name TEXT,birth_date TEXT,email_verified_at TEXT);CREATE TABLE numi_orders(id TEXT PRIMARY KEY,account_id TEXT,product_code TEXT,resource_id TEXT,amount_kopeks INT,currency TEXT DEFAULT 'RUB',provider TEXT,status TEXT DEFAULT 'pending',verified_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE numi_entitlements(id TEXT PRIMARY KEY,account_id TEXT,order_id TEXT UNIQUE,product_code TEXT,resource_id TEXT,status TEXT,expires_at TEXT);CREATE TABLE numi_checkouts(id TEXT PRIMARY KEY,account_id TEXT,request_key TEXT,cart_hash TEXT,amount_kopeks INT,provider_payment_id TEXT,confirmation_url TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(account_id,request_key));CREATE TABLE numi_checkout_items(checkout_id TEXT,order_id TEXT PRIMARY KEY);CREATE TABLE numi_subscription_settings(account_id TEXT,product_code TEXT,auto_renew INT DEFAULT 0,payment_method_id TEXT,consent_at TEXT,cancelled_at TEXT,source_order_id TEXT,PRIMARY KEY(account_id,product_code));CREATE TABLE numi_checkout_consents(checkout_id TEXT,product_code TEXT,consent_at TEXT,version TEXT,PRIMARY KEY(checkout_id,product_code))");
