$checkout['provider_payment_id']='test-payment-1';$payment=['id'=>'test-payment-1','test'=>true,'paid'=>true,'status'=>'succeeded','amount'=>['value'=>'490.00','currency'=>'RUB'],'metadata'=>['numi_checkout'=>$checkout['id']],'payment_method'=>['saved'=>true,'id'=>'opaque-method-1']];
naStoreApply($db,$checkout,$payment);naStoreApply($db,$checkout,$payment);
$ent=$db->query('SELECT * FROM numi_entitlements')->fetch();ok($ent['status']==='active','subscription activated');ok(naMaterialEntitlement($db,$alice,$ent['id'])!==null,'owner material allowed');ok(naMaterialEntitlement($db,['id'=>'bob'],$ent['id'])===null,'other account denied');
$setting=$db->query('SELECT * FROM numi_subscription_settings')->fetch();ok((int)$setting['auto_renew']===1&&$setting['payment_method_id']==='opaque-method-1','verified saved method and consent activate renewal');
naSubscriptionCancel($db,$alice,'club_month');$setting=$db->query('SELECT * FROM numi_subscription_settings')->fetch();ok((int)$setting['auto_renew']===0,'cancel renewal');ok(naMaterialEntitlement($db,$alice,$ent['id'])!==null,'cancel keeps paid period');
$until=$ent['expires_at'];$renew=naStorePrepareCheckout($db,$alice,['request_key'=>'manual-renewal-0002'], $quote);$renew['provider_payment_id']='test-payment-2';$payment2=$payment;$payment2['id']='test-payment-2';$payment2['metadata']['numi_checkout']=$renew['id'];unset($payment2['payment_method']);naStoreApply($db,$renew,$payment2);
$latest=$db->query('SELECT MAX(expires_at) FROM numi_entitlements')->fetchColumn();ok($latest>$until,'renewal stacks onto remaining period');ok((int)$db->query('SELECT COUNT(*) FROM numi_entitlements')->fetchColumn()===2,'one right per paid renewal');ok((int)$db->query('SELECT auto_renew FROM numi_subscription_settings')->fetchColumn()===0,'manual renewal does not re-enable consent');
$db->exec("UPDATE numi_entitlements SET expires_at='2000-01-01 00:00:00'");ok(!naCatalogHasAccess($db,$alice,'club_month','club'),'expired rights denied');ok(naSubscriptionState('2000-01-01 00:00:00')==='expired','expired state');
