$bobCheckout=naStorePrepareCheckout($db,['id'=>'bob'],['request_key'=>'bob-purchase-0001','auto_renew_consent'=>true],$quote);$bobCheckout['provider_payment_id']='bob-payment';naSubscriptionCancel($db,['id'=>'bob'],'club_month');$bobPayment=$payment;$bobPayment['id']='bob-payment';$bobPayment['metadata']['numi_checkout']=$bobCheckout['id'];naStoreApply($db,$bobCheckout,$bobPayment);ok((int)$db->query("SELECT auto_renew FROM numi_subscription_settings WHERE account_id='bob'")->fetchColumn()===0,'cancellation during payment wins');
$db->exec("CREATE TABLE numi_sessions(session_hash TEXT PRIMARY KEY,account_id TEXT,expires_at TEXT)");
